def artist_ids(row):
    return [r.get("navigationEndpoint", {}).get("browseEndpoint", {}).get("browseId") for col in row.get("flexColumns", [])[1:] for r in col.get("musicResponsiveListItemFlexColumnRenderer", {}).get("text", {}).get("runs", [])]
def is_audio(row):
    return row.get("overlay", {}).get("musicItemThumbnailOverlayRenderer", {}).get("content", {}).get("musicPlayButtonRenderer", {}).get("playNavigationEndpoint", {}).get("watchEndpoint", {}).get("watchEndpointMusicSupportedConfigs", {}).get("watchEndpointMusicConfig", {}).get("musicVideoType") == "MUSIC_VIDEO_TYPE_ATV"
