def clean(value):
    if isinstance(value, dict): return {k: clean(v) for k,v in value.items() if k not in ("trackingParams", "clickTrackingParams", "menu", "multiSelectCheckbox", "accessibilityPauseData", "accessibilityPlayData")}
    if isinstance(value, list): return [clean(v) for v in value]
    return value
